const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // Read the HTML file
  const htmlPath = path.join(__dirname, 'qs-rankings-poster.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 2000));

  // Get the rendered SVG from the infographic container
  const svgData = await page.evaluate(async () => {
    const container = document.getElementById('container');
    if (container && container.querySelector('svg')) {
      const svg = container.querySelector('svg');
      return 'data:image/svg+xml;base64,' + Buffer.from(svg.outerHTML).toString('base64');
    }
    return null;
  });

  if (svgData) {
    // Save SVG
    fs.writeFileSync(path.join(__dirname, 'output', 'final_poster.svg'), svgData);
    console.log('SVG saved to output/final_poster.svg');

    // Also try to create a simple placeholder PNG header
    // For full PNG conversion, we'd need sharp or canvas
    console.log('Note: For full PNG, using sharp to convert SVG...');
  } else {
    console.log('SVG not found - infographic may not have rendered');
  }

  await browser.close();
})();

