const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'qs-rankings-poster.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 3000));

  // Debug: get container content
  const containerHtml = await page.evaluate(() => {
    const c = document.getElementById('container');
    return c ? c.innerHTML.substring(0, 500) : 'container not found';
  });
  console.log('Container HTML:', containerHtml);

  // Try to get the SVG
  const svgData = await page.evaluate(async () => {
    const container = document.getElementById('container');
    if (!container) return null;
    const svg = container.querySelector('svg');
    if (!svg) return null;
    const serializer = new XMLSerializer();
    const svgString = serializer.serializeToString(svg);
    return 'data:image/svg+xml;base64,' + Buffer.from(svgString).toString('base64');
  });

  if (svgData) {
    fs.writeFileSync(path.join(__dirname, 'output', 'final_poster.svg'), svgData, 'base64');
    console.log('SVG saved');
  } else {
    console.log('No SVG found');
  }

  await browser.close();
})();

