const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

(async () => {
  const svgPath = path.join(__dirname, 'output', 'final_poster.svg');
  const pngPath = path.join(__dirname, 'output', 'final_poster.png');

  const svgBuffer = fs.readFileSync(svgPath);
  console.log('SVG size:', svgBuffer.length);

  // Get SVG dimensions from the file
  const svgString = svgBuffer.toString();
  const viewBoxMatch = svgString.match(/viewBox="([^"]+)"/);
  const widthMatch = svgString.match(/width="([^"]+)"/);
  const heightMatch = svgString.match(/height="([^"]+)"/);

  let width = 800;
  let height = 1400;

  if (widthMatch && heightMatch) {
    width = parseFloat(widthMatch[1]);
    height = parseFloat(heightMatch[1]);
  }

  console.log('Converting to PNG:', width, 'x', height);

  await sharp(svgBuffer)
    .resize(width, height, { fit: 'contain', background: { r: 10, g: 22, b: 40, alpha: 1 } })
    .png()
    .toFile(pngPath);

  console.log('PNG saved to output/final_poster.png');

  const stats = fs.statSync(pngPath);
  console.log('PNG size:', stats.size, 'bytes');
})();

