const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  page.on('console', msg => console.log('PAGE LOG:', msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  const htmlPath = 'file://' + path.resolve(__dirname, 'qs-rankings-poster.html');
  console.log('Loading:', htmlPath);

  await page.goto(htmlPath, { waitUntil: 'networkidle0' });
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 2000));

  // Set viewport to match poster dimensions
  await page.setViewport({ width: 800, height: 1400, deviceScaleFactor: 2 });

  // Wait for render
  await new Promise(r => setTimeout(r, 1000));

  // Take screenshot
  const screenshotPath = path.join(__dirname, 'output', 'final_poster.png');
  await page.screenshot({
    path: screenshotPath,
    type: 'png',
    fullPage: true
  });

